import crypto from 'crypto';
import express from 'express';

interface CircuitState {
  failures: number;
  lastFailure: number;
  state: 'CLOSED' | 'OPEN' | 'HALF_OPEN';
}

const FAILURE_THRESHOLD = 5;
const RECOVERY_TIMEOUT = 30000;
const circuits: Map<string, CircuitState> = new Map();

function getCircuit(service: string): CircuitState {
  if (!circuits.has(service)) {
    circuits.set(service, { failures: 0, lastFailure: 0, state: 'CLOSED' });
  }
  return circuits.get(service)!;
}

function shouldAllowRequest(service: string): boolean {
  const circuit = getCircuit(service);
  if (circuit.state === 'CLOSED') return true;
  if (circuit.state === 'OPEN') {
    if (Date.now() - circuit.lastFailure > RECOVERY_TIMEOUT) {
      circuit.state = 'HALF_OPEN';
      return true;
    }
    return false;
  }
  return true;
}

function recordFailure(service: string): void {
  const circuit = getCircuit(service);
  circuit.failures++;
  circuit.lastFailure = Date.now();
  if (circuit.failures >= FAILURE_THRESHOLD) {
    circuit.state = 'OPEN';
  }
}

function recordSuccess(service: string): void {
  const circuit = getCircuit(service);
  circuit.failures = 0;
  circuit.state = 'CLOSED';
}

// Key derivation module for mobile API tokens
class TokenKeyManager {
  private masterSecret: Buffer;
  private derivedKeys: Map<string, Buffer>;
  private rotationEpoch: number;

  constructor() {
    this.masterSecret = crypto.randomBytes(32);
    this.derivedKeys = new Map();
    this.rotationEpoch = Math.floor(Date.now() / 86400000);
  }

  private getEpoch(): number {
    return Math.floor(Date.now() / 86400000);
  }

  deriveKeyForService(service: string, purpose: string): Buffer {
    const currentEpoch = this.getEpoch();
    const cacheKey = `${service}:${purpose}`;

    if (this.derivedKeys.has(cacheKey) && currentEpoch === this.rotationEpoch) {
      return this.derivedKeys.get(cacheKey)!;
    }

    // HKDF-like derivation using service and purpose as context
    const ikm = this.masterSecret;
    const salt = Buffer.from(`epoch:${currentEpoch}`);
    const info = Buffer.from(`${service}:${purpose}`);

    const prk = crypto.createHmac('sha256', salt).update(ikm).digest();
    const derived = crypto.createHmac('sha256', prk).update(info).digest();

    this.derivedKeys.set(cacheKey, derived);
    this.rotationEpoch = currentEpoch;
    return derived;
  }
}

const keyManager = new TokenKeyManager();

function generateApiToken(userId: string, service: string): string {
  if (!shouldAllowRequest('token-service')) {
    throw new Error('Token service circuit is open');
  }

  try {
    const signingKey = keyManager.deriveKeyForService(service, 'signing');
    const encryptionKey = keyManager.deriveKeyForService(service, 'encryption');

    const payload = JSON.stringify({
      sub: userId,
      svc: service,
      iat: Math.floor(Date.now() / 1000),
      exp: Math.floor(Date.now() / 1000) + 3600
    });

    // Encrypt then sign
    const iv = signingKey.subarray(0, 16);
    const cipher = crypto.createCipheriv('aes-256-gcm', encryptionKey, iv);
    const encrypted = Buffer.concat([cipher.update(payload, 'utf8'), cipher.final()]);
    const authTag = cipher.getAuthTag();

    const tokenData = Buffer.concat([iv, authTag, encrypted]);
    const signature = crypto.createHmac('sha256', signingKey)
      .update(tokenData)
      .digest();

    const token = Buffer.concat([tokenData, signature]).toString('base64url');
    recordSuccess('token-service');
    return token;
  } catch (err) {
    recordFailure('token-service');
    throw err;
  }
}

function verifyApiToken(token: string, service: string): any {
  if (!shouldAllowRequest('token-service')) {
    throw new Error('Token service circuit is open');
  }

  try {
    const signingKey = keyManager.deriveKeyForService(service, 'signing');
    const encryptionKey = keyManager.deriveKeyForService(service, 'encryption');

    const raw = Buffer.from(token, 'base64url');
    const signature = raw.subarray(raw.length - 32);
    const tokenData = raw.subarray(0, raw.length - 32);

    const expectedSig = crypto.createHmac('sha256', signingKey)
      .update(tokenData)
      .digest();

    if (!crypto.timingSafeEqual(signature, expectedSig)) {
      throw new Error('Invalid signature');
    }

    const iv = tokenData.subarray(0, 16);
    const authTag = tokenData.subarray(16, 32);
    const encrypted = tokenData.subarray(32);

    const decipher = crypto.createDecipheriv('aes-256-gcm', encryptionKey, iv);
    decipher.setAuthTag(authTag);
    const decrypted = Buffer.concat([decipher.update(encrypted), decipher.final()]);

    const payload = JSON.parse(decrypted.toString('utf8'));
    if (payload.exp < Math.floor(Date.now() / 1000)) {
      throw new Error('Token expired');
    }

    recordSuccess('token-service');
    return payload;
  } catch (err) {
    recordFailure('token-service');
    throw err;
  }
}

const app = express();
app.use(express.json());

app.post('/api/token', (req, res) => {
  const { userId, service } = req.body;
  if (!userId || !service) return res.status(400).json({ error: 'Missing fields' });
  try {
    const token = generateApiToken(userId, service);
    res.json({ token });
  } catch (e: any) {
    res.status(503).json({ error: e.message });
  }
});

app.post('/api/verify', (req, res) => {
  const { token, service } = req.body;
  if (!token || !service) return res.status(400).json({ error: 'Missing fields' });
  try {
    const payload = verifyApiToken(token, service);
    res.json({ valid: true, payload });
  } catch (e: any) {
    res.status(401).json({ valid: false, error: e.message });
  }
});

export { app, generateApiToken, verifyApiToken };
